import{_ as i,a0 as a,w as l,s as p,ao as u,I as o,x as n,a1 as s,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中 | LCTT x X-CMD","titleTemplate":false,"description":"Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140804 Linux FAQs with Answers--How to check if I am in a running screen session","title":"Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中","tag":"201408","desc":""},"relativePath":"201408/20140804 Linux FAQs with Answers--How to check if I am in a running screen session.md","filePath":"[post].md"}'),c={name:"201408/20140804 Linux FAQs with Answers--How to check if I am in a running screen session.md"};function m(x,e,d,f,T,_){const t=a("Link");return l(),p("div",null,[e[11]||(e[11]=u(`<h1 id="linux-faq与答案-如何检查我是否处于一个运行着的screen会话中" tabindex="-1">Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中 <a class="header-anchor" href="#linux-faq与答案-如何检查我是否处于一个运行着的screen会话中" aria-label="Permalink to “Linux FAQ与答案：如何检查我是否处于一个运行着的screen会话中”">​</a></h1><blockquote><p><strong>问题</strong>：我经常使用screen命令来运行多个伪终端会话。好多次，我发现都记不得自己是否在一个screen会话中，还是在一个常规终端中。是否有一种简便的方法来检查我是否在一个运行着的screen会话中？</p></blockquote><p>一个快捷而又简单的方法来检查你是否处于一个screen伪终端中，还是在一个常规终端中，就是检查STY环境变量。当调用了screen，就会把STY变量值设置为会话名。因此，如果STY环境变量被设置为任何非空字符串，就意味着你正处于一个screen会话中。</p><pre><code> $ echo $STY 
</code></pre><blockquote><p>2858.pts-3.my_host</p></blockquote><p>然而，请注意，上面的方法<strong>只有当</strong>你是在本地计算机上运行screen命令的时候。如果你从本地计算机的screen会话中SSH到任何远程计算机上，远程计算机上的STY变量不会被设置，尽管在技术上看，你仍然处于一个screen会话中。</p><p>事实上，一个更为可靠的检查你是否处于一个screen会话中的方法，是按“Ctrl-a”+“Ctrl-t”。如果你处于screen会话中，终端会在底部显示时间信息。</p><p><img src="https://farm6.staticflickr.com/5578/14821730712_6a139d72e9_z.jpg" alt=""></p><hr>`,9)),o("p",null,[e[1]||(e[1]=n("via: ",-1)),s(t,{href:"http://ask.xmodulo.com/check-running-screen-session.html"},{default:r(()=>[...e[0]||(e[0]=[n("http://ask.xmodulo.com/check-running-screen-session.html",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=n("译者：",-1)),s(t,{href:"https://github.com/GOLinux"},{default:r(()=>[...e[2]||(e[2]=[n("GOLinux",-1)])]),_:1}),e[5]||(e[5]=n(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[n("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=n("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[n("LCTT",-1)])]),_:1}),e[9]||(e[9]=n(" 原创翻译，",-1)),s(t,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[n("Linux中国",-1)])]),_:1}),e[10]||(e[10]=n(" 荣誉推出",-1))])])}const k=i(c,[["render",m]]);export{A as __pageData,k as default};
